m;padding:.8rem;text-align:center;height:100%}.risk-modal-kpi small{display:block;color:#7b8499}.risk-modal-kpi strong{font-size:1.25rem;color:#263754}.risk-change{border-left:3px solid #4e73df;background:#f8f9fc;padding:.55rem .7rem;margin:.45rem 0;border-radius:.25rem;font-size:.8rem}.risk-status-Pendiente{background:#fff4d6;color:#9d6a00}.risk-status-Enproceso{background:#edf2ff;color:#3657b3}.risk-status-Completada{background:#e8f8ef;color:#18854b}.risk-status-Cancelada{background:#f1f2f4;color:#667085}.risk-model-warning{border-left:4px solid #f6c23e}.risk-loading{padding:4rem;text-align:center;color:#6e7891}@media(max-width:767px){.risk-bar-row{grid-template-columns:95px 1fr 35px}.risk-title{font-size:1.1rem}.risk-actions .btn{width:100%;margin-bottom:.25rem}}
