<script>
(function($){
 const API='risk_dashboard_api.php',CSRF=<?php echo json_encode($csrf); ?>; let cache=null,currentStudent=null;
 const esc=v=>$('<div>').text(v==null?'':v).html(); const pct=v=>(Number(v||0)*100).toFixed(1)+'%';
 const statusClass=s=>'risk-status-'+String(s||'').replace(/\s+/g,'');
 function params(){const q=new URLSearchParams({action:'dashboard'});[['level','#risk-level'],['grade','#risk-grade'],['section','#risk-section'],['bimestre','#risk-bimester']].forEach(([k,s])=>{let v=$(s).val();if(v)q.set(k,v)});return q.toString()}
 function notice(text,type='warning'){$('#risk-alert').html('<div class="alert alert-'+type+'">'+esc(text)+'</div>')}
 function card(label,value,tone,icon){return '<div class="col-xl-3 col-md-6 mb-3"><div class="risk-card"><div class="d-flex justify-content-between"><div><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong></div><span class="risk-icon risk-'+tone+'"><i class="fas '+icon+'"></i></span></div></div></div>'}
 function factorText(f){if(!f)return '';let raw=Number(f.value||0),v=f.feature==='attendance_rate_30d'?raw.toFixed(1)+'%':(['grade_mean_current','grade_mean_previous','grade_trend'].includes(f.feature)?raw.toFixed(2):raw.toFixed(0));return esc(f.label||f.feature)+': '+v}
 async function load(){ $('#risk-loading').removeClass('d-none');$('#risk-content').addClass('d-none');$('#risk-alert').empty();try{let r=await fetch(API+'?'+params(),{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo cargar el panel.');cache=d;render(d)}catch(e){notice(e.message,'danger')}finally{$('#risk-loading').addClass('d-none')}}
 function render(d){$('#risk-content').removeClass('d-none');if(!d.model.available)notice('El modelo debe reentrenarse con la política temporal de bimestres cerrados antes de mostrar predicciones.','warning');else if(!d.migration_ready)notice('La predicción funciona, pero falta ejecutar sql/predictive_interventions_upgrade.sql para registrar intervenciones.','warning');
 let s=d.summary||{};$('#risk-cards').html(card('Riesgo alto',s.high||0,'danger','fa-exclamation-triangle')+card('Riesgo medio',s.medium||0,'warning','fa-exclamation-circle')+card('Riesgo bajo',s.low||0,'success','fa-check-circle')+card('Evaluados',s.evaluated||0,'primary','fa-users'));
 let rows='';(d.predictions||[]).forEach(x=>{let st=x.student,f=(x.factors||[]).map(factorText).join('<br>'),base=x.bimester_label||x.bimester,target=x.target_bimester_label||x.target_bimester;rows+='<tr><td><strong>'+esc(st.name)+'</strong><div class="text-muted small">'+esc(base)+' cerrado → riesgo en '+esc(target)+(x.base_closed_at?' · corte '+esc(x.base_closed_at):'')+'</div></td><td>'+esc(st.nivel)+'<br>'+esc(st.grado)+'° '+esc(st.seccion)+'</td><td><span class="risk-badge risk-badge-'+esc(x.level)+'">'+esc(x.level)+' · '+pct(x.probability)+'</span></td><td class="risk-factor">'+(f||'Sin factor dominante')+'</td><td class="text-center"><span class="badge badge-light border">'+esc(x.open_interventions||0)+'</span></td><td class="text-right risk-actions"><button class="btn btn-sm btn-outline-primary risk-sim" data-id="'+st.id+'"><i class="fas fa-project-diagram"></i></button><button class="btn btn-sm btn-primary risk-new" data-id="'+st.id+'"><i class="fas fa-hands-helping"></i></button></td></tr>'});$('#risk-students').html(rows||'<tr><td colspan="6" class="risk-empty">No hay predicciones disponibles. Verifica que exista un bimestre cerrado y un modelo v3 entrenado.</td></tr>');
 let factors=d.factors||[],max=Math.max(...factors.map(x=>Number(x.count||0)),1),fh='';factors.forEach(x=>fh+='<div class="risk-bar-row"><span>'+esc(x.label)+'</span><div class="risk-track"><div class="risk-fill" style="width:'+(Number(x.count||0)/max*100)+'%"></div></div><strong>'+esc(x.count)+'</strong></div>');$('#risk-factors').html(fh||'<div class="risk-empty">Sin factores agregados.</div>');
 renderInterventions(d.interventions||[],d.intervention_summary||{});let e=d.effectiveness||{};$('#risk-effectiveness').html('<div class="row"><div class="col-6 mb-2"><div class="risk-modal-kpi"><small>Intervenciones medidas</small><strong>'+esc(e.measured||0)+'</strong></div></div><div class="col-6 mb-2"><div class="risk-modal-kpi"><small>Con menor riesgo</small><strong>'+esc(e.improved||0)+'</strong></div></div></div>'+(e.average_probability_reduction!=null?'<div class="alert alert-light border mt-2 mb-0"><strong>Reducción media observada:</strong> '+(Number(e.average_probability_reduction)*100).toFixed(1)+' puntos porcentuales.<div class="risk-note mt-1">Es una comparación antes/después; por sí sola no prueba causalidad.</div></div>':'<div class="risk-empty">Las mediciones posteriores aparecen cuando exista un nuevo bimestre cerrado después de la intervención.</div>'))}
 function renderInterventions(rows,sum){let html='';rows.forEach(r=>html+='<tr><td><strong>'+esc(r.student_name)+'</strong><div class="small text-muted">'+esc(r.nivel)+' · '+esc(r.grado)+'° '+esc(r.seccion)+'</div></td><td>'+esc(r.intervention_type)+'<div class="small text-muted">'+esc(r.title)+'</div></td><td><span class="risk-badge '+statusClass(r.status)+'">'+esc(r.status)+'</span>'+(r.status==='Completada'&&r.post_risk_probability==null?'<div class="small text-muted mt-1">Medición posterior pendiente</div>':'')+'</td><td>'+esc(r.followup_date||'—')+'</td><td>'+(r.risk_probability!=null?pct(r.risk_probability):'—')+'</td><td class="text-right"><button class="btn btn-sm btn-outline-secondary risk-edit" data-id="'+r.id+'"><i class="fas fa-edit"></i></button></td></tr>');$('#risk-interventions').html(html||'<tr><td colspan="6" class="risk-empty">Todavía no hay intervenciones registradas.</td></tr>');$('#risk-intervention-kpis').text('Pendientes: '+(sum['Pendiente']||0)+' · En proceso: '+(sum['En proceso']||0)+' · Seguimientos vencidos: '+(sum['Seguimientos vencidos']||0))}
 function findPrediction(id){return (cache?.predictions||[]).find(x=>Number(x.student.id)===Number(id))}
 async function studentDetail(id){let r=await fetch(API+'?action=student&student_id='+encodeURIComponent(id),{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo consultar al estudiante.');return d}
 $(document).on('click','.risk-sim',async function(){try{let d=await studentDetail($(this).data('id'));currentStudent=d.student;let cf=d.counterfactual,p=d.prediction;if(!cf.available){$('#risk-scenario-body').html('<div class="alert alert-warning">No hay información suficiente o no existe un bimestre cerrado válido para simular cambios.</div>')}else{let rec=cf.recommended,base=p.bimester_label||p.bimester,target=p.target_bimester_label||p.target_bimester,h='<div class="alert alert-light border"><strong>Base:</strong> '+esc(base)+' bimestre cerrado'+(p.base_closed_at?' ('+esc(p.base_closed_at)+')':'')+' · <strong>Objetivo:</strong> riesgo en '+esc(target)+' bimestre.</div><div class="row mb-3"><div class="col-6"><div class="risk-modal-kpi"><small>Riesgo estimado</small><strong>'+esc(p.level)+' · '+pct(p.probability)+'</strong></div></div><div class="col-6"><div class="risk-modal-kpi"><small>Escenario recomendado</small><strong>'+(rec?esc(rec.level)+' · '+pct(rec.probability):'Ya es bajo')+'</strong></div></div></div>';if(rec){h+='<h6 class="font-weight-bold">'+esc(rec.name)+'</h6>';rec.changes.forEach(c=>h+='<div class="risk-change"><strong>'+esc(c.label)+'</strong>: '+(c.feature==='attendance_rate_30d'?Number(c.before).toFixed(1)+'%':Number(c.before).toFixed(1))+' → '+(c.feature==='attendance_rate_30d'?Number(c.after).toFixed(1)+'%':Number(c.after).toFixed(1))+'</div>')}h+='<div class="alert alert-light border mt-3 mb-0"><i class="fas fa-info-circle mr-1"></i>Simulación del comportamiento del modelo. No constituye una predicción causal ni garantiza que estas acciones produzcan exactamente ese cambio.</div>';$('#risk-scenario-body').html(h)}$('#riskScenarioModal').modal('show')}catch(e){notice(e.message,'danger')}});
 function openNew(id){let x=findPrediction(id);if(!x)return;currentStudent=x.student;$('#risk-int-student').val(x.student.id);$('#risk-int-student-label').html('<strong>'+esc(x.student.name)+'</strong><br><small>'+esc(x.student.nivel)+' · '+esc(x.student.grado)+'° '+esc(x.student.seccion)+' · riesgo '+esc(x.level)+' '+pct(x.probability)+'</small>');$('#risk-int-type').val(x.suggested?.type||'Seguimiento tutorial');$('#risk-int-title').val(x.suggested?.title||'Seguimiento preventivo de riesgo académico');$('#riskInterventionModal').modal('show')}
 $(document).on('click','.risk-new',function(){openNew($(this).data('id'))});$('#risk-scenario-intervene').on('click',function(){if(currentStudent){$('#riskScenarioModal').modal('hide');openNew(currentStudent.id)}});
 $('#risk-intervention-form').on('submit',async function(e){e.preventDefault();let fd=new FormData(this);fd.set('action','create_intervention');fd.set('csrf_token',CSRF);try{let r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo guardar.');$('#riskInterventionModal').modal('hide');notice(d.message,'success');this.reset();load()}catch(err){notice(err.message,'danger')}});
 $(document).on('click','.risk-edit',function(){let id=Number($(this).data('id')),r=(cache?.interventions||[]).find(x=>Number(x.id)===id);if(!r)return;$('#risk-up-id').val(r.id);$('#risk-up-label').html('<strong>'+esc(r.student_name)+'</strong><br><small>'+esc(r.intervention_type)+' · '+esc(r.title)+'</small>');$('#risk-up-status').val(r.status);$('#risk-up-outcome').val(r.outcome||'');$('#risk-up-followup').val(r.followup_date||'');$('#risk-up-notes').val(r.notes||'');$('#riskUpdateModal').modal('show')});
 $('#risk-update-form').on('submit',async function(e){e.preventDefault();let fd=new FormData(this);fd.set('action','update_intervention');fd.set('csrf_token',CSRF);try{let r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo actualizar.');$('#riskUpdateModal').modal('hide');notice(d.message,'success');load()}catch(err){notice(err.message,'danger')}});
 $('#risk-refresh,#risk-apply').on('click',load); load();
})(jQuery);
</script>